{
  "Ethical_Stabilizers": {
    "is_used": "No",
    "explanation": "While Wilbur Ross attempts to frame himself as adhering to rules ('fully and properly disclosed', 'scrupulous'), the narrative primarily focuses on the conflict regarding his disclosures rather than establishing him as a moral guardian or peacemaker. The text does not portray any participant successfully maintaining social cohesion or justice through ethical mediation."
  },
  "Altruistic_Catalysts": {
    "is_used": "No",
    "explanation": "There are no individuals or groups portrayed as challenging the status quo for liberation, nor as martyrs or underdogs driving systemic change through sacrifice."
  },
  "Overt_Aggressors": {
