  "Ethical_Stabilizers": {
    "is_used": "Yes",
    "explanation": "The U.S. Justice Department and Assistant Attorney General John Carlin are framed as Guardians protecting national security and public safety. They are portrayed as proactive authorities establishing a team to 'secure' the internet of things and address vulnerabilities before they can be exploited, thereby maintaining social cohesion and preventing harm."
  },
  "Altruistic_Catalysts": {
    "is_used": "No",
    "explanation": "While the text mentions experts noting that self-driving cars could reduce fatalities, this is presented as general expert opinion rather than a narrative framing of specific individuals or groups as Rebels, Martyrs, or Underdogs driving systemic change through sacrifice or challenging the status quo."
  },
  "Overt_Aggressors": {
    "is_used": "Yes",
